TLM.f("Sancti/06-12o",{"officium":"Ss. Basilidis, Cyrinis, Naboris et Nazarii Martyrum","rule":["vide C3;","Gloria"],"fallback":"Commune/C3","from":{"Introitus":"Commune/C3","Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 78:11-12; 78:10"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."},{"k":"ref","la":"Ps 78:1"},{"k":"text","la":"Deus, venérunt gentes in hereditátem tuam: polluérunt templum sanctum tuum: posuérunt Jerúsalem in pomórum custódiam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."}],"Oratio":[{"k":"text","la":"Sanctórum Mártyrum tuórum Basílidis, Cyríni, Nabóris atque Nazárii, quǽsumus, Dómine, natalítia nobis votíva respléndeant: et, quod illis cóntulit excelléntia sempitérna, frúctibus nostræ devotiónis accréscat."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 10:32-38"},{"k":"text","la":"Fratres: Rememorámini prístinos dies, in quibus illumináti magnum certámen sustinuístis passiónum: et in áltero quidem oppróbriis et tribulatiónibus spectáculum facti: in áltero autem sócii táliter conversántium effécti. Nam et vinctis compássi estis, et rapínam bonórum vestrórum cum gáudio suscepístis, cognoscéntes vos habere meliórem et manéntem substántiam. Nolíte itaque amíttere confidéntiam vestram, quæ magnam habet remuneratiónem. Patiéntia enim vobis necéssaria est: ut, voluntátem Dei faciéntes, reportétis promissiónem. Adhuc enim módicum aliquántulum, qui ventúrus est, véniet, et non tardábit. Justus autem meus ex fide vivit."}],"Graduale":[{"k":"ref","la":"Ps 78:10; 78:2"},{"k":"text","la":"Víndica, Dómine, sánguinem Sanctórum tuórum, qui effúsus est."},{"k":"text","la":"Posuérunt mortália servórum tuórum escas volatílibus cœli: carnes Sanctórum tuórum béstiis terræ.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:14"},{"k":"text","la":"Córpora Sanctórum in pace sepúlta sunt: et nómina eórum vivent in generatiónem et generatiónem. Allelúja."}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 24:3-13"},{"k":"text","la":"In illo témpore: Sedénte Jesu super montem Olivéti, accessérunt ad eum discípuli secréto, dicéntes: Dic nobis, quando hæc erunt? et quod signum advéntus tui et consummatiónis sǽculi? Et respóndens Jesus, dixit eis: Vidéte, ne quis vos sedúcat. Multi enim vénient in nómine meo, dicéntes: Ego sum Christus: et multos sedúcent. Auditúri enim estis prælia et opiniónes prœliórum. Vidéte, ne turbémini. Opórtet enim hæc fíeri, sed nondum est finis. Consúrget enim gens in gentem, et regnum in regnum, et erunt pestiléntiæ et fames et terræmótus per loca. Hæc autem ómnia inítia sunt dolórum. Tunc tradent vos in tribulatiónem et occídent vos: et éritis odio ómnibus géntibus propter nomen meum. Et tunc scandalizabúntur multi, et ínvicem tradent, et odio habébunt ínvicem. Et multi pseudoprophétæ surgent, et sedúcent multos. Et quóniam abundávit iníquitas, refrigéscet cáritas multórum. Qui autem perseveráverit usque in finem, hic salvus erit."}],"Offertorium":[{"k":"ref","la":"Ps 149:5-6"},{"k":"text","la":"Exsultábunt Sancti in glória, lætabúntur in cubílibus suis: exaltatiónes Dei in fáucibus eórum, allelúja."}],"Secreta":[{"k":"text","la":"Pro sanctórum tuórum Basílidis, Cyríni, Nabóris atque Nazárii sánguine venerándo, hóstias tibi. Dómine, sollémniter immolámus, tua mirabília pertractántes: per quem talis est perfécta victória."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 78:2; 78:11"},{"k":"text","la":"Posuérunt mortália servórum tuórum, Dómine, escas volatílibus cœli, carnes Sanctórum tuórum béstiis terræ: secúndum magnitúdinem bráchii tui pósside fílios morte punitórum."}],"Postcommunio":[{"k":"text","la":"Semper, Dómine, sanctórum Mártyrum tuórum Basílidis, Cyríni, Nabóris atque Nazárii sollémnia celebrántes: præsta, quǽsumus; ut eórum patrocínia júgiter sentiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"97cd5daa004a17ee":{"t":"<i>Pomolimo se</i>.\nNeka nam zasine, molimo, Gospodine, posvećeni, rođendan svetih mučenika tvojih Bazilida, Cirina, Nabora i Nazarija, i neka ono što je njima dala neprolazna veličina, uveća plodove naše pobožnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, neka nam zasjaju svetkovine svetih Basilida, Cirina, Nabora i Nazarija, mučenika, i neka ono, što im je dala vječna veličina, bude još veće plodom naše pobožnosti, po G: n.","knRef":"Kniewald 1942, str. 594–595 (snimka 298) (OCR)"},"18a7be86ceccdf44":{"t":"Da počastimo krv svetih tvojih Bazilida, Cirina, Nabora i Nazarija, po kojoj je stečena tolika pobjeda, svečano ti, Gospodine, prinosimo darove obavljajući tvoje divne tajne.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svečano Ti, Gospodine, prikazujemo žrtve 0 svetkovini mučeništva svetih Tvojih Basilida, Cirina, Nabora i Nazarija, vršeći Tvoja divna otajstva, po kojima je postignuta tolika pobjeda, po G. n.","knRef":"Kniewald 1942, str. 594–595 (snimka 298) (OCR)"},"66e31205765105d4":{"t":"<i>Pomolimo se</i>.\nDok uvijek slavimo, Gospodine, svetkovinu svetih mučenika tvojih Bazilida, Cirina, Nabora i Nazarija, podaj nam, molimo, da stalno osjećamo i njihovu zaštitu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svetkujući svečanost svetih Tvojih mučenika, Basilida, Cirina, Nabora i Nazarijai, molimo Te, Gospodine, da bez prestanka osjećamo njihovu zaštitu, po G. n.","knRef":"Kniewald 1942, str. 594–595 (snimka 298) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}]}}});
